import type { GeneratorPatternSpec } from "./paper-generator-engine.ts";

export type PaperGeneratorSlug =
  | "graph-paper-generator" | "lined-paper-generator" | "dot-grid-paper-generator"
  | "isometric-paper-generator" | "hexagonal-paper-generator" | "triangle-grid-generator"
  | "coordinate-plane-generator" | "polar-graph-paper-generator" | "semi-log-paper-generator"
  | "log-log-paper-generator" | "perspective-grid-generator" | "engineering-paper-generator"
  | "cornell-notes-generator" | "handwriting-practice-paper" | "seyes-ruled-paper-generator"
  | "chinese-character-practice-paper-generator" | "music-staff-paper";

export type GeneratorValues = {
  spacingMm: number; lineWidthMm: number; secondary: number; tertiary: number;
  option: string; toggle: boolean; patternColor: string; accentColor: string;
};

export type GeneratorControl = {
  key: keyof Pick<GeneratorValues, "spacingMm" | "lineWidthMm" | "secondary" | "tertiary">;
  label: string; min: number; max: number; step: number; unit?: "length" | "number" | "degrees";
};

export type PaperGeneratorDefinition = {
  slug: PaperGeneratorSlug; name: string; shortName: string; description: string; intro: string;
  explanation: string; uses: string[]; controls: GeneratorControl[];
  option?: { label: string; values: Array<[string, string]> };
  toggle?: string;
  sizeGuide?: { heading: string; note?: string; columns: string[]; rows: string[][] };
  defaults: GeneratorValues;
  presets: Array<{ name: string; values: Partial<GeneratorValues> }>;
  faqs: Array<{ question: string; answer: string }>;
  guide?: Array<{ heading: string; paragraphs: string[] }>;
  related: PaperGeneratorSlug[];
  build: (values: GeneratorValues) => GeneratorPatternSpec;
};

const base = (spacingMm: number, overrides: Partial<GeneratorValues> = {}): GeneratorValues => ({ spacingMm, lineWidthMm: 0.16, secondary: 5, tertiary: 10, option: "default", toggle: true, patternColor: "#8fb3da", accentColor: "#385f8d", ...overrides });
const commonFaq = (name: string) => [
  { question: `Can I print this ${name} at actual size?`, answer: "Yes. PDF is the most predictable format. In the print dialog choose Actual size or 100% and disable Fit to page." },
  { question: "Which paper sizes are supported?", answer: "A3, A4, A5, US Letter, and US Legal are available in portrait or landscape orientation." },
];

